/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// Service class to run the update Nat3040 report number
/// </summary>
class METNat3040RegisterUpdateService extends SysOperationServiceBase
{
  
}

Method.Source:
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Checks if run in batch or not.
    /// </summary>
    public void processOperation(METNat3040RegisterUpdateContract _contract)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        NumberSeq               num;
        Num                     number;
        NoYesId UpdateNat3040 = _contract.parmUpdateNat3040();
        str     Nat3040Number = _contract.parmNat3040Number();
        ttsbegin;
        num     = NumberSeq::newGetNum(VendParameters::numRefNat30Number());
        number  = num.num();

        update_recordset metExciseRegisterEntry     
            setting Nat3040ReportNumber = number
            where metExciseRegisterEntry.CustomerExempt      == NoYes::No
            &&    metExciseRegisterEntry.Nat3040ReportNumber == '';

        num.used();
        ttscommit;

        this.nat3040export(UpdateNat3040,Nat3040Number);
   
    }

    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// based on the input parameters filter the records from METExciseRegister table and store in csv
    /// </summary>
    /// <param name = "_UpdateNat3040"> NoYesId</param>
    /// <param name = "_Nat3040Number"> Nat30/40 Report Number </param>
    private void nat3040export(NoYesId _UpdateNat3040,str _Nat3040Number)
    {
    
        CommaStreamIo io = CommaStreamIo::constructForWrite();
        str     fileName = 'NAT30_.csv', fileContent;

        io.writeExp(['ItemNo', 'Tariff Item Code', 'Stat Code', 'LALS Quantity',
                     'Customs Value','Origin Country Code','Preference Scheme',
                     'Preference Rule','DataAreaId']);

        METExciseRegisterEntry  metExciseRegisterEntry;
        
        while select sum(DutyRate),sum(LitresOfAlcoholCalculated) from metExciseRegisterEntry
            group by ItemNo,TariffItemCode,DutyOriginCountryCode
            where metExciseRegisterEntry.OriginType == METOriginType::SalesOrder
            &&    metExciseRegisterEntry.Nat3040ReportNumber ==  _Nat3040Number
            &&    metExciseRegisterEntry.DataAreaId          ==  'LIQ'
       {
           real CustomsValue = metExciseRegisterEntry.DutyRate *  metExciseRegisterEntry.LitresOfAlcoholCalculated;
           // Write line
           io.writeExp([metExciseRegisterEntry.ItemNo,metExciseRegisterEntry.TariffItemCode,metExciseRegisterEntry.StatCode,
                        metExciseRegisterEntry.LitresOfAlcoholCalculated,CustomsValue,metExciseRegisterEntry.DutyOriginCountryCode,
                        metExciseRegisterEntry.PreferenceScheme,metExciseRegisterEntry.PreferenceRule,metExciseRegisterEntry.DataAreaId]);
       
       }

            // Set stream
            System.IO.Stream stream = io.getStream();
            stream.Position = 0;

            // Set stream reader
            System.IO.StreamReader sReader = new System.IO.StreamReader(stream);

            // Set file contentn string
            fileContent = sReader.ReadToEnd();

        }
